		// 0x06000099, x86-64 0x19DD5A0: a miss formats the boxed value as uppercase hex and caches it.
		public static string GetString(this ErrorTypes value)
		{
			string result;
			if (!ErrorTypesEnumToString.TryGetValue(value, out result))
			{
				result = string.Format("0x{0:X}", value);
				ErrorTypesEnumToString[value] = result;
			}
			return result;
		}
